if(vTopeUFAFPPlc!==''&&sldImp!==0&&_TDINA_!==0&&$('#diasTrabjd_dsp').val()!=='0'){let tipo_sueldo=$('#tipoSuel').val();let dias_trabajados=$("#diasTrabjd").val();let dias_subsidio_parcial=$('#diasTotalesSubsPrcl').val();let dias_totales_con_subsidio_parcial=0;let dias_trabajador_final=0;if(tipo_sueldo==='H'){dias_totales_con_subsidio_parcial=parseFloat(dias_trabajados)+parseInt(dias_subsidio_parcial);}else if((parseInt(dias_trabajados)+parseInt(dias_subsidio_parcial))>30){dias_totales_con_subsidio_parcial=30;}else{dias_totales_con_subsidio_parcial=parseInt(dias_trabajados)+parseInt(dias_subsidio_parcial);}
if(dias_subsidio_parcial!==0){dias_trabajador_final=(dias_totales_con_subsidio_parcial-(dias_subsidio_parcial/2));}else{dias_trabajador_final=dias_trabajados;}
sldImp=parseInt(Math.round((vTopeUFAFPPlc/30)*dias_trabajador_final));document.getElementById("aplhbimp_sd").value=parseInt(sldImp);}else if(_TDINA_!==0&&$('#diasTrabjd_dsp').val()!=='0'){sldImp=sldImp/30*$('#diasTrabjd_dsp').val();}
