console.log("Renta imponible mes:",renta_imponible_cesantia);console.log("total calculado:",sbTtlTrbj,sbTtlEmpIndf);if(element===''){document.getElementById("sbTtlSgrCstTrbj").value=sbTtlTrbj;document.getElementById("sbTtlSgrCstEmpIndf").value=sbTtlEmpIndf;}else{document.getElementById("afcTrab_emp").value=sbTtlTrbj;}
