function _js_clcTtlMontoSaludSbsds(ttlPlnIspr){var form=document.getElementById("agrLiquidacion_form");var mntPro=0;var ctIntsaReg=form.MAXInascia.value;var dt=0;for(var cont=1;cont<=ctIntsaReg;cont++){if(document.getElementById("da_intsa_"+cont)!==null&&($("#inas_movt_"+cont).val()==="4"||$("#inas_movt_"+cont).val()==="7")){if($('#pro_sld_adcnl_'+cont).val()==='S'&&ttlPlnIspr!==0){dt=document.getElementById("inas_movt_rl_"+cont).value==='100'?(document.getElementById("da_intsa_"+cont).value/2):document.getElementById("da_intsa_"+cont).value;mntPro+=Math.round((ttlPlnIspr/30)*dt);}else{mntPro+=Math.round(((_js_getTpAfp(document.getElementById("rmcn_imp_"+cont).value)/30)*document.getElementById("da_intsa_"+cont).value)*(document.getElementById("_PG_PCSLDIPS").value/100));}}}
return mntPro;}
function _js_clcMtlSgrdd(){var prcnMtlBs=document.getElementById("_PG_PCCMUTESG").value;var prcnMtlAdncl=0;var vTopeUFAFPPlc=parseInt(document.getElementById("tpAFP").value);var sldImp=parseInt(document.getElementById("sbTtlHbrsImpnbl").value);if(sldImp>vTopeUFAFPPlc){sldImp=js_clcRntPrpSldSprTpConSb(vTopeUFAFPPlc,'');}
prcnMtlAdncl=document.getElementById("_PE_PRCTSADNL").value;var prncTtlMtl=(parseFloat(prcnMtlBs)+parseFloat(prcnMtlAdncl))/100;var sbTtlMtlMsAdcnl=0;if($('#tAfpIps').val()==='1'||$('#idNCNLD').val()!=='1'){sbTtlMtlMsAdcnl=Math.round(prncTtlMtl*_js_getTpAfp(sldImp));}else if($('#tAfpIps').val()==='2'){sbTtlMtlMsAdcnl=Math.round(prncTtlMtl*_js_getTpIPS(document.getElementById("sbTtlHbrsImpnbl").value));}else if($('#idTPTRBJDR').val()==='3'&&$('#PrevAntigua').val()==='1'){sbTtlMtlMsAdcnl=Math.round(prncTtlMtl*_js_getTpAfp(sldImp));}else if($('#idTPTRBJDR').val()==='3'&&$('#PrevAntigua').val()==='2'){sbTtlMtlMsAdcnl=Math.round(prncTtlMtl*_js_getTpIPS(document.getElementById("sbTtlHbrsImpnbl").value));}else{sbTtlMtlMsAdcnl=Math.round(prncTtlMtl*_js_getTpAfp(sldImp));}
if($("#tieen_mtl").val()==='S'){document.getElementById("sbTtlMtl").value=sbTtlMtlMsAdcnl;}else{document.getElementById("sbTtlMtl").value=0;}}
function _js_clcTtlDiasProporcionalIsapre(){var form=document.getElementById("agrLiquidacion_form");var _TDINA_=0;var dt=0;var ctIntsaReg=form.MAXInascia.value;for(var cont=1;cont<=ctIntsaReg;cont++){if(document.getElementById("da_intsa_"+cont)!==null&&($("#inas_movt_"+cont).val()==="4"||$("#inas_movt_"+cont).val()==="7"||$("#inas_movt_"+cont).val()==="14"||$("#inas_movt_"+cont).val()==="15")){dt=document.getElementById("inas_movt_rl_"+cont).value==='100'?(document.getElementById("da_intsa_"+cont).value/2):document.getElementById("da_intsa_"+cont).value;_TDINA_=_TDINA_+parseInt(dt);}}
return _TDINA_;}
