function _js_clcCtzcnCsPrtculr(form){if(document.getElementById("sbTtlCtzcnCsPrtcl")!==null){var fini=new Date("2020/10/01");var fp=$("#fProceso").val().split("-");var fpro=new Date(fp[2],(fp[1]-1),fp[0]).getTime();if(fpro>=fini.getTime()){var afc=0.03;document.getElementById("sbTtlSgrCstEmpFjo").value=Math.round(afc*_js_getTpAfp(document.getElementById("sbTtlHbrsImpnbl").value));}
var prcCsPrclr=(document.getElementById("_PG_PCCTZCSPRT").value/100);document.getElementById("sbTtlCtzcnCsPrtcl").value=Math.round(prcCsPrclr*_js_getTpAfp(document.getElementById("sbTtlHbrsImpnbl").value));var ctIntsaReg=form.MAXInascia.value;var di=0;for(var cont=1;cont<=ctIntsaReg;cont++){if(document.getElementById("da_intsa_"+cont)!==null&&document.getElementById("rmcn_imp_"+cont)!==null&&(document.getElementById("inas_movt_"+cont).value==="4"||document.getElementById("inas_movt_"+cont).value==="7")){var rntBase=0;if(document.getElementById("prcnAfp")!==null){rntBase=_js_getTpAfp((document.getElementById("rmcn_imp_"+cont).value));}else if(document.getElementById("sbTtlRgm")!==null){rntBase=_js_getTpIPS(document.getElementById("rmcn_imp_"+cont).value);}else{rntBase=_js_getTpAfp((document.getElementById("rmcn_imp_"+cont).value));}
di=(document.getElementById("inas_movt_rl_"+cont)!==null&&document.getElementById("inas_movt_rl_"+cont).value==='100')?(document.getElementById("da_intsa_"+cont).value/2):document.getElementById("da_intsa_"+cont).value;rntBase=Math.round((rntBase/30).toFixed(3))*di;document.getElementById("sbTtlSgrCstEmpFjo").value=parseInt(document.getElementById("sbTtlSgrCstEmpFjo").value)+Math.round(afc*rntBase);document.getElementById("sbTtlCtzcnCsPrtcl").value=parseInt(document.getElementById("sbTtlCtzcnCsPrtcl").value)+Math.round(prcCsPrclr*rntBase);}}}}
