function _analiticaPdfFillIndicadores($tpl,DtJson,tipo){var act=DtJson.info[DtJson.info.ANNO_ACT];var ant=DtJson.info[DtJson.info.ANNO_ANT];$tpl.find('#pdf-mes-myr-vts').text(act.MAYOR_VENTAS.MES);$tpl.find('#pdf-mnt-myr-vts').text($.number(act.MAYOR_VENTAS.MONTO,0,'','.'));$tpl.find('#pdf-mes-mnr-vts').text(act.MENOR_VENTAS.MES);$tpl.find('#pdf-mnt-mnr-vts').text($.number(act.MENOR_VENTAS.MONTO,0,'','.'));$tpl.find('#pdf-ttl-vts-act').text($.number(act.TOTAL_VENTAS,0,'','.'));$tpl.find('#pdf-ttl-vts-ant').text($.number(ant.TOTAL_VENTAS,0,'','.'));$tpl.find('#pdf-pro-vts-act').text($.number(Math.round(act.TOTAL_VENTAS/act.PROMEDIO_VENTAS),0,'','.'));$tpl.find('#pdf-pro-vts-ant').text($.number(Math.round(ant.TOTAL_VENTAS/ant.PROMEDIO_VENTAS),0,'','.'));$tpl.find('#pdf-vts-primer-smstr').text($.number(act.SEMESTRES.PRIMER,0,'','.'));$tpl.find('#pdf-vts-segundo-smstr').text($.number(act.SEMESTRES.SEGUNDO,0,'','.'));$tpl.find('#pdf-afe-vts-act').text($.number(act.TOTAL_AFECTO,0,'','.'));$tpl.find('#pdf-afe-vts-ant').text($.number(ant.TOTAL_AFECTO,0,'','.'));$tpl.find('#pdf-exe-vts-act').text($.number(act.TOTAL_EXENTO,0,'','.'));$tpl.find('#pdf-exe-vts-ant').text($.number(ant.TOTAL_EXENTO,0,'','.'));if(tipo==='1'){var crecimiento=(((act.TOTAL_VENTAS/ant.TOTAL_VENTAS)-1)*100);$tpl.find('#pdf-mnt-crecimiento').text($.number(crecimiento,2,',','.')+'%');$tpl.find('#pdf-mnt-aumdis').text($.number(act.TOTAL_VENTAS-ant.TOTAL_VENTAS,0,'','.'));}}
function _pdfParseCsvBarra(csvStr){var lines=csvStr.trim().split('\n');var headers=lines[0].split(',');var years=headers.slice(1);var cats=[];var data=years.map(function(){return[];});lines.slice(1).forEach(function(row){var cols=row.split(',');if(!cols[0])return;cats.push(cols[0]);years.forEach(function(y,i){data[i].push(parseFloat(cols[i+1])||0);});});return{categories:cats,series:years.map(function(y,i){return{name:y,data:data[i]};})};}
function _pdfParseCsvPie(csvStr){var lines=csvStr.trim().split('\n');var pts=[];lines.slice(1).forEach(function(row){var cols=row.split(',');if(!cols[0]||!cols[1])return;pts.push([cols[0],parseFloat(cols[1])||0]);});return pts;}
function _drawBarOnCanvas(canvas,parsed,title,colors,w,h){canvas.width=w;canvas.height=h;var ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,w,h);var cats=parsed.categories;var series=parsed.series;var nSer=series.length;var nCats=cats.length;if(!nCats||!nSer)return;var maxVal=0;series.forEach(function(s){s.data.forEach(function(v){if(v>maxVal)maxVal=v;});});if(!maxVal)return;var padLeft=62;var padRight=12;var padTop=32;var padBottom=44;var plotW=w-padLeft-padRight;var plotH=h-padTop-padBottom;ctx.font='bold 12px Arial, Helvetica, sans-serif';ctx.fillStyle='#333333';ctx.textAlign='center';ctx.textBaseline='top';ctx.fillText(title,w/2,6);var nTicks=5;var rawInterval=maxVal/nTicks;var magnitude=Math.pow(10,Math.floor(Math.log10(rawInterval)));var niceSteps=[1,2,2.5,5,10];var tickInterval=magnitude*10;for(var ni=0;ni<niceSteps.length;ni++){var candidate=niceSteps[ni]*magnitude;if(candidate>=rawInterval){tickInterval=candidate;break;}}
var yMax=tickInterval*Math.ceil(maxVal/tickInterval);var nGridlines=Math.round(yMax/tickInterval);ctx.font='9px Arial, Helvetica, sans-serif';ctx.fillStyle='#666666';ctx.textAlign='right';ctx.textBaseline='middle';for(var ti=0;ti<=nGridlines;ti++){var gVal=ti*tickInterval;var gy=padTop+plotH-(gVal/yMax)*plotH;ctx.strokeStyle=ti===0?'#aaaaaa':'#e8e8e8';ctx.lineWidth=ti===0?1:0.5;ctx.beginPath();ctx.moveTo(padLeft,gy);ctx.lineTo(padLeft+plotW,gy);ctx.stroke();var lbl=gVal>=1000000?((gVal/1000000)%1===0?(gVal/1000000)+'M':(gVal/1000000).toFixed(1)+'M'):(gVal>=1000?(gVal/1000)+'K':gVal);ctx.fillText(lbl,padLeft-4,gy);}
var catW=plotW/nCats;var groupPad=catW*0.12;var barGap=1;var barW=Math.max(2,(catW-groupPad*2-barGap*(nSer-1))/nSer);ctx.font='8px Arial, Helvetica, sans-serif';ctx.textAlign='center';for(var ci=0;ci<nCats;ci++){var groupX=padLeft+ci*catW+groupPad;for(var si=0;si<nSer;si++){var val=(series[si].data[ci])||0;var bH=(val/yMax)*plotH;var bX=groupX+si*(barW+barGap);var bY=padTop+plotH-bH;ctx.fillStyle=colors[si%colors.length];ctx.fillRect(bX,bY,barW,bH);}
ctx.fillStyle='#555555';ctx.textBaseline='top';ctx.fillText(cats[ci],padLeft+ci*catW+catW/2,padTop+plotH+4);}
var legItemW=60;var legTotalW=nSer*legItemW;var legX=(w-legTotalW)/2;var legY=h-14;for(var li=0;li<nSer;li++){var lx=legX+li*legItemW;ctx.fillStyle=colors[li%colors.length];ctx.fillRect(lx,legY,10,10);ctx.font='9px Arial, Helvetica, sans-serif';ctx.fillStyle='#333333';ctx.textAlign='left';ctx.textBaseline='top';ctx.fillText(series[li].name,lx+13,legY);}
ctx.save();ctx.translate(9,padTop+plotH/2);ctx.rotate(-Math.PI/2);ctx.font='9px Arial, Helvetica, sans-serif';ctx.fillStyle='#666666';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('Pesos (CLP)',0,0);ctx.restore();}
function _drawPieOnCanvas(canvas,pts,title,colors,w,h){canvas.width=w;canvas.height=h;var ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,w,h);var total=0;pts.forEach(function(p){total+=p[1];});if(!total)return;var titleH=30;var cx=w*0.36;var cy=titleH+(h-titleH)*0.52;var r=Math.min((h-titleH)*0.44,w*0.28);ctx.font='bold 12px Arial, Helvetica, sans-serif';ctx.fillStyle='#333333';ctx.textAlign='center';ctx.textBaseline='top';ctx.fillText(title,w/2,7);var angle=-Math.PI/2;pts.forEach(function(pt,i){var slice=(pt[1]/total)*Math.PI*2;ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,r,angle,angle+slice);ctx.closePath();ctx.fillStyle=colors[i%colors.length];ctx.fill();ctx.strokeStyle='#ffffff';ctx.lineWidth=1.5;ctx.stroke();var pct=pt[1]/total*100;if(pct>4){var mid=angle+slice/2;var lx=cx+Math.cos(mid)*r*0.60;var ly=cy+Math.sin(mid)*r*0.60;ctx.font='bold 9px Arial, Helvetica, sans-serif';ctx.fillStyle='#ffffff';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(pct.toFixed(1)+'%',lx,ly);}
angle+=slice;});var legX=cx+r+14;var legY0=titleH+6;var rowH=Math.min(16,Math.max(10,(h-legY0-8)/pts.length));pts.forEach(function(pt,i){var ly=legY0+i*rowH;if(ly+rowH>h-4)return;ctx.fillStyle=colors[i%colors.length];ctx.fillRect(legX,ly+2,9,9);var pct=(pt[1]/total*100).toFixed(1)+'%';var lbl=pt[0]+': '+pct;var maxW=w-legX-12;ctx.font='9px Arial, Helvetica, sans-serif';ctx.fillStyle='#333333';ctx.textAlign='left';ctx.textBaseline='top';while(ctx.measureText(lbl).width>maxW&&lbl.length>5){lbl=lbl.slice(0,-2)+'…';}
ctx.fillText(lbl,legX+12,ly+2);});}
function _analiticaPdfBuildCharts($tpl,DtJson,tipo,callback){var esVentas=tipo==='1';var tipoLabel=esVentas?'Ventas':'Compras';var W_BAR=650;var W_PIE=esVentas?320:650;var W_LINE=320;var H_BAR=esVentas?300:310;var H_PIE=230;var H_LINE=230;var barParsed=_pdfParseCsvBarra(JSON.parse(DtJson.grafbarra));var pieParsed=_pdfParseCsvPie(JSON.parse(DtJson.grafPie));var canvasBar=document.createElement('canvas');canvasBar.style.cssText='display:block;';$tpl.find('#pdf-c1').empty().append(canvasBar);_drawBarOnCanvas(canvasBar,barParsed,tipoLabel+' Mensuales',colColors,W_BAR,H_BAR);var canvas=document.createElement('canvas');canvas.style.cssText='display:block;';$tpl.find('#pdf-c2').empty().append(canvas);_drawPieOnCanvas(canvas,pieParsed,'Distribución '+tipoLabel+' '+DtJson.info.ANNO_ACT,pieColors,W_PIE,H_PIE);if(esVentas){$tpl.find('#pdf-c3').highcharts({chart:{type:'line',width:W_LINE,height:H_LINE,animation:false},title:{text:'Crecimiento %',x:-20},yAxis:{title:{text:'Ventas ($)'},plotLines:[{value:0,width:1,color:'#808080'}]},data:{csv:JSON.parse(DtJson.grafLineal)},tooltip:{valueSuffix:'%'},legend:{layout:'vertical',align:'right',verticalAlign:'middle',borderWidth:0},credits:{enabled:false}});}
setTimeout(callback,500);}
