function _drawLineOnCanvas(canvas,categorias,seriesData,title,w,h){canvas.width=w;canvas.height=h;var ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,w,h);var nCats=categorias?categorias.length:0;if(!nCats||!seriesData.length)return;var padLeft=72;var padRight=16;var padTop=30;var padBottom=52;var plotW=w-padLeft-padRight;var plotH=h-padTop-padBottom;var allVals=[];seriesData.forEach(function(s){allVals=allVals.concat(s.data);});var rawMax=Math.max.apply(null,allVals);var rawMin=Math.min.apply(null,allVals);if(rawMin>0)rawMin=0;var range=rawMax-rawMin||1;var rawIntvl=range/5;var mag=Math.pow(10,Math.floor(Math.log10(Math.abs(rawIntvl)||1)));var niceArr=[1,2,2.5,5,10];var tickIntvl=mag*10;for(var ni=0;ni<niceArr.length;ni++){if(niceArr[ni]*mag>=rawIntvl){tickIntvl=niceArr[ni]*mag;break;}}
var yMin=tickIntvl*Math.floor(rawMin/tickIntvl);var yMax=tickIntvl*Math.ceil(rawMax/tickIntvl);var yRange=yMax-yMin||1;function yC(v){return padTop+plotH-((v-yMin)/yRange)*plotH;}
function xC(i){return nCats>1?padLeft+(i/(nCats-1))*plotW:padLeft+plotW/2;}
ctx.font='bold 12px Arial, Helvetica, sans-serif';ctx.fillStyle='#333333';ctx.textAlign='center';ctx.textBaseline='top';ctx.fillText(title,w/2,6);var nGrid=Math.round((yMax-yMin)/tickIntvl);ctx.font='9px Arial, Helvetica, sans-serif';ctx.textAlign='right';ctx.textBaseline='middle';for(var gi=0;gi<=nGrid;gi++){var yv=yMin+gi*tickIntvl;var yc2=yC(yv);ctx.strokeStyle=yv===0?'#aaaaaa':'#eeeeee';ctx.lineWidth=yv===0?1.5:1;ctx.beginPath();ctx.moveTo(padLeft,yc2);ctx.lineTo(padLeft+plotW,yc2);ctx.stroke();ctx.fillStyle='#666666';ctx.fillText(_numFmtShort(yv),padLeft-4,yc2);}
var step=Math.max(1,Math.ceil(nCats/8));ctx.font='8px Arial, Helvetica, sans-serif';ctx.fillStyle='#666666';ctx.textAlign='center';ctx.textBaseline='top';for(var ci=0;ci<nCats;ci+=step){ctx.fillText(categorias[ci],xC(ci),padTop+plotH+4);}
if(seriesData.length>=3){var dif=seriesData[2].data;var y0c=yC(0);ctx.globalAlpha=0.25;for(var pi=0;pi<dif.length-1;pi++){var v1=dif[pi],v2=dif[pi+1];var px1=xC(pi),px2=xC(pi+1);var py1=yC(v1),py2=yC(v2);if(v1>=0&&v2>=0){ctx.fillStyle='#0ca30c';ctx.beginPath();ctx.moveTo(px1,y0c);ctx.lineTo(px1,py1);ctx.lineTo(px2,py2);ctx.lineTo(px2,y0c);ctx.closePath();ctx.fill();}else if(v1<=0&&v2<=0){ctx.fillStyle='#d03b3b';ctx.beginPath();ctx.moveTo(px1,y0c);ctx.lineTo(px1,py1);ctx.lineTo(px2,py2);ctx.lineTo(px2,y0c);ctx.closePath();ctx.fill();}else{var t=v1/(v1-v2);var pxCros=px1+t*(px2-px1);if(v1>0){ctx.fillStyle='#0ca30c';ctx.beginPath();ctx.moveTo(px1,y0c);ctx.lineTo(px1,py1);ctx.lineTo(pxCros,y0c);ctx.closePath();ctx.fill();ctx.fillStyle='#d03b3b';ctx.beginPath();ctx.moveTo(pxCros,y0c);ctx.lineTo(px2,py2);ctx.lineTo(px2,y0c);ctx.closePath();ctx.fill();}else{ctx.fillStyle='#d03b3b';ctx.beginPath();ctx.moveTo(px1,y0c);ctx.lineTo(px1,py1);ctx.lineTo(pxCros,y0c);ctx.closePath();ctx.fill();ctx.fillStyle='#0ca30c';ctx.beginPath();ctx.moveTo(pxCros,y0c);ctx.lineTo(px2,py2);ctx.lineTo(px2,y0c);ctx.closePath();ctx.fill();}}}
ctx.globalAlpha=1;}
var colors=['#2a78d6','#eb6834','#0ca30c'];seriesData.forEach(function(s,si){if(!s.data.length)return;ctx.strokeStyle=colors[si]||'#888888';ctx.lineWidth=si===2?1.5:2.5;ctx.lineJoin='round';ctx.beginPath();s.data.forEach(function(v,i){if(i===0)ctx.moveTo(xC(i),yC(v));else ctx.lineTo(xC(i),yC(v));});ctx.stroke();});var legendItems=seriesData.map(function(s,si){return{name:s.name,color:colors[si]||'#888888'};});ctx.font='9px Arial, Helvetica, sans-serif';var lx=0;var ly=padTop+plotH+28;var totalW=legendItems.reduce(function(acc,it){return acc+14+ctx.measureText(it.name).width+10;},0);lx=(w-totalW)/2;ctx.textAlign='left';ctx.textBaseline='middle';legendItems.forEach(function(it){ctx.fillStyle=it.color;ctx.fillRect(lx,ly,9,9);ctx.fillStyle='#333333';ctx.fillText(it.name,lx+13,ly+4);lx+=13+ctx.measureText(it.name).width+10;});}
