if(window._rcvDocumentosDescuadrados&&window._rcvDocumentosDescuadrados.length>0){Swal.fire({icon:'question',title:'Gestión de cuadre',html:'¿Ha terminado la gestión de cuadre manual?<br>'
+'<small>Al confirmar se utilizarán los montos ajustados en el panel de cuadre.<br>'
+'Si cancela, puede continuar ajustando antes de importar.</small>',showCancelButton:true,confirmButtonText:'Sí, importar ahora',cancelButtonText:'No, seguir ajustando',allowOutsideClick:false,allowEscapeKey:false,}).then(function(r){if(r.isConfirmed){window._rcvCuadreOverridesJsonActivo=_rcvGetCuadreOverridesJson();_rcvEjecutarImportacion(tipoRCV,id_request);}});return;}
