function _rcvCalcularLotes(totalPendientes,tamLote,limiteTotal){let lotes=[];let enviado=0;let n=1;while(enviado<totalPendientes&&enviado<limiteTotal){let restante=Math.min(totalPendientes-enviado,limiteTotal-enviado);let tam=Math.min(tamLote,restante);let inicio=enviado+1;let fin=enviado+tam;lotes.push({offset:enviado,limite:tam,label:'Lote '+n,inicio:inicio,fin:fin});enviado+=tam;n++;}
return lotes;}
function jsImportarPorLotes(tipoRCV,id_request,form,config,totalPendientes){let lotes=_rcvCalcularLotes(totalPendientes,config.cantidad_por_lote,config.limite_total);let interrumpir=false;let importadosTotal=0;let itemsHtml=lotes.map(function(l,i){return'<div class="rcv-lote-item" id="rcv_lote_item_'+i+'">'
+'<span class="rcv-lote-estado rcv-lote-pendiente"><i class="fa fa-circle-o"></i></span> '
+'<span>'+l.label+' (docs '+l.inicio+'–'+l.fin+')</span>'
+'</div>';}).join('');let msgEnProcesoHtml=totalPendientes>config.limite_total?'<div id="rcv_lotes_msg_en_proceso" class="msg-moderno msg-warning margin_top_9px">'
+'<strong>Aviso:</strong> Solo se procesarán <strong>'+config.limite_total+'</strong> de los '
+'<strong>'+totalPendientes+'</strong> documentos pendientes. '
+'Esta limitación es una medida de prevención para evitar problemas de rendimiento. '
+'Una vez finalizado este proceso, inicie una nueva importación para continuar con los documentos restantes.'
+'</div>':'';let dialogHtml='<div id="rcv_lotes_dialog">'
+msgEnProcesoHtml
+'<div id="rcv_lotes_lista" class="margin_bottom_9px">'+itemsHtml+'</div>'
+'<div class="margin_top_9px">'
+'Documentos importados: <strong><span id="rcv_lotes_contador">0</span></strong>'
+' de <strong>'+Math.min(totalPendientes,config.limite_total)+'</strong>'
+'</div>'
+'<div id="rcv_lotes_msg_limite" class="msg-moderno msg-warning margin_top_9px" style="display:none">'
+'Se alcanzó el máximo de documentos a importar en un mismo envío, continúe con la importación de documentos en otro proceso de importación.'
+'</div>'
+'<div id="rcv_lotes_msg_interrumpiendo" class="margin_top_9px" style="display:none">'
+'<i class="fa fa-spinner fa-spin"></i> Interrumpiendo...</div>'
+'</div>';$('body').append(dialogHtml);$('#rcv_lotes_dialog').dialog({title:'Importación por lotes',width:480,modal:true,dialogClass:'ui-dialog-modern',position:{my:'center',at:'center',of:window},buttons:[{text:'Interrumpir',id:'btn_rcv_interrumpir_lotes',class:'btn-minimalist btn-minimalist-red',click:function(){interrumpir=true;$('#btn_rcv_interrumpir_lotes').prop('disabled',true).text('Interrumpiendo...');$('#rcv_lotes_msg_interrumpiendo').show();}}],close:function(){$('#content_modal_importacion_rcv').html('<div class="text-center" style="padding:40px 0;">'
+'<i class="fa fa-cog fa-spin" style="font-size:52px;color:#888;"></i>'
+'</div>');JSClassAjax.prototype.Call({url:'index.php',data:'finc=preparaModalImportacionRCV_v2&'+new URLSearchParams({end:'#content_modal_importacion_rcv',id_request:id_request,id_empresa_seleccionada:$('#GidEMP').val(),id_usuario:$('#2K4RH231H').val()}).toString(),type:'GET',dataType:'json'});$(this).dialog('destroy').remove();}});window.rcvOnLoteCompletado=function(idx,importados,abortar){importadosTotal+=importados;let $item=$('#rcv_lote_item_'+idx);$item.find('.rcv-lote-estado').removeClass('rcv-lote-pendiente rcv-lote-en-progreso').addClass('rcv-lote-completado').html('<i class="fa fa-check-circle"></i>');$item.append(' <small>('+importados+' importados)</small>');$('#rcv_lotes_contador').text(importadosTotal);if(abortar||interrumpir){_rcvFinalizarLotes(tipoRCV,id_request,importadosTotal,false);return;}
if(importadosTotal>=config.limite_total){$('#rcv_lotes_msg_en_proceso').hide();$('#rcv_lotes_msg_limite').show();_rcvFinalizarLotes(tipoRCV,id_request,importadosTotal,false);return;}
let siguiente=idx+1;if(siguiente>=lotes.length){_rcvFinalizarLotes(tipoRCV,id_request,importadosTotal,true);}else{_rcvEnviarLote(siguiente,lotes,tipoRCV,id_request,form);}};_rcvEnviarLote(0,lotes,tipoRCV,id_request,form);}
function _rcvCompactarFormCta(formString){let params=new URLSearchParams(formString);let neg1Ids=[];let out=new URLSearchParams();for(let[key,value]of params.entries()){let match=key.match(/^cta_\[(\d+)\]$/);if(match&&value==='-1'){neg1Ids.push(match[1]);}else{out.append(key,value);}}
if(neg1Ids.length>0){out.set('cta_neg1_ids',neg1Ids.join(','));}
return out.toString();}
