var selectCuenta='<select name="cta_['+doc.folio+']" class="js-select2-rcv-doc select2-royal" style="width:100%">'
+optsSelect+'</select>';var celdaFolio=esDescuadre?'<i class="fa fa-exclamation-triangle margin_der_4px" aria-hidden="true" '
+'style="color:#c0392b;" '
+'title="Factura descuadrada: la suma de componentes no coincide con el monto total"></i>'
+_rcvEscHtml(String(doc.folio)):_rcvEscHtml(String(doc.folio));var celdaAccion='';if(doc.id_voucherImportacion){celdaAccion+='<a class="puntero"><span class="btn-action-glow btn-glow-azul-os" '
+'onclick="popInfoMessage(\'Documento ya ha sido importado con voucher '+_rcvEscHtml(String(doc.comprobante||''))+'\')">'
+'<i class="fa fa-check"></i></span></a>';}
